import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { apiDb, apiAuth } from '../services/api'; 
import { Shield, AlertTriangle, CheckCircle, XCircle, Eye, ArrowLeft, LogOut, Ban, FileCheck, Info, Loader2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const POLLING_INTERVAL = 15000; 

const AdminReports = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedReport, setSelectedReport] = useState(null);
  const [error, setError] = useState(null);

  const fetchReports = useCallback(async () => {
    const isAdmin = localStorage.getItem('adminSession') === 'true';

    if (!isAdmin) {
      navigate('/admin-login');
      return;
    }

    try {
      // --- FIX: Using the newly defined API route ---
      const reportsResponse = await apiDb.getAllReports();

      const reportsData = reportsResponse.map(doc => ({ 
        id: doc._id || doc.id, 
        ...doc 
      }));

      reportsData.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

      setReports(reportsData);
      setError(null);
    } catch (err) {
      console.error('❌ Error fetching reports:', err);
      // NOTE: Your previous error was "Chat not found" which usually means 404
      setError('Error loading reports. Check if the /api/chats/reports endpoint is running correctly.'); 
    } finally {
      setLoading(false);
    }
  }, [navigate]);

  useEffect(() => {
    setLoading(true);
