    setLoading(true);
    try {
      // Placeholder: Call API to ban user and block chat
      // await apiDb.processReport(report.id, 'approve', { reportedUserId: report.reportedUser, chatId: report.chatId });
      alert('✅ Placeholder: User banned and chat blocked.');
      fetchReports();
